namespace sv_6453f116814f4120ba8a7d34fdf5b09e.Services;

public class AppointmentService
{
    public Task<List<string>> GetDoctorsAsync()
    {
        return Task.FromResult(new List<string>
        {
            "Dr. Smith",
            "Dr. Johnson",
            "Dr. Patel",
            "Dr. Williams"
        });
    }

    public Task<List<string>> GetAvailableTimeSlotsAsync(string doctor, DateOnly date)
    {
        // Stub: return fixed slots regardless of doctor/date
        return Task.FromResult(new List<string>
        {
            "9:00 AM",
            "10:00 AM",
            "11:00 AM",
            "1:00 PM",
            "2:00 PM",
            "3:00 PM"
        });
    }

    /// <summary>
    /// Validates patient info against server-side business rules.
    /// Returns a dictionary of field name -> error message for any failures.
    /// </summary>
    public Task<Dictionary<string, string>> ValidatePatientAsync(
        string email,
        string insuranceProvider,
        string doctor,
        string timeSlot)
    {
        var errors = new Dictionary<string, string>();

        if (string.Equals(email, "taken@example.com", StringComparison.OrdinalIgnoreCase))
        {
            errors[nameof(BookAppointmentModel.Email)] = "Account has outstanding balance";
        }

        if (insuranceProvider == "None" && doctor == "Dr. Smith")
        {
            errors[nameof(BookAppointmentModel.Doctor)] = "Selected doctor does not accept self-pay patients";
        }

        if (timeSlot == "10:00 AM")
        {
            errors[nameof(BookAppointmentModel.TimeSlot)] = "This slot is no longer available";
        }

        return Task.FromResult(errors);
    }
}

public class BookAppointmentModel
{
    // Step 1
    public string PatientName { get; set; } = string.Empty;
    public string Email { get; set; } = string.Empty;
    public string Phone { get; set; } = string.Empty;
    public string InsuranceProvider { get; set; } = string.Empty;

    // Step 2
    public string Doctor { get; set; } = string.Empty;
    public DateTime? AppointmentDate { get; set; }
    public string TimeSlot { get; set; } = string.Empty;
    public string ReasonForVisit { get; set; } = string.Empty;
}

@page "/book-appointment"
@rendermode InteractiveServer
@using sv_6453f116814f4120ba8a7d34fdf5b09e.Services
@inject AppointmentService AppointmentService

<PageTitle>Book Appointment</PageTitle>

<h3 class="mb-4">Book a Medical Appointment</h3>

<EditForm Model="Model" OnValidSubmit="HandleSubmit" FormName="bookAppointment">
    <DataAnnotationsValidator />

    @* ───── STEP 1 ───── *@
    <fieldset>
        <legend>Patient Information</legend>

        <div class="mb-3">
            <label class="form-label" for="patientName">Patient Name</label>
            <InputText id="patientName" class="form-control" @bind-Value="Model.PatientName" />
            <ValidationMessage For="() => Model.PatientName" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="email">Email</label>
            <InputText id="email" class="form-control" @bind-Value="Model.Email" />
            <ValidationMessage For="() => Model.Email" />
            @if (serverErrors.ContainsKey(nameof(Model.Email)))
            {
                <div class="validation-message">@serverErrors[nameof(Model.Email)]</div>
            }
        </div>

        <div class="mb-3">
            <label class="form-label" for="phone">Phone</label>
            <InputText id="phone" class="form-control" @bind-Value="Model.Phone" />
            <ValidationMessage For="() => Model.Phone" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="insurance">Insurance Provider</label>
            <InputSelect id="insurance" class="form-select" @bind-Value="Model.InsuranceProvider">
                <option value="">-- Select --</option>
                <option value="Aetna">Aetna</option>
                <option value="BlueCross">BlueCross</option>
                <option value="Cigna">Cigna</option>
                <option value="UnitedHealth">UnitedHealth</option>
                <option value="None">None</option>
            </InputSelect>
            <ValidationMessage For="() => Model.InsuranceProvider" />
        </div>

        @if (!showStep2)
        {
            <button type="button" class="btn btn-primary" @onclick="ProceedToStep2">
                Next
            </button>
        }
    </fieldset>

    @* ───── STEP 2 ───── *@
    @if (showStep2)
    {
        <fieldset class="mt-4">
            <legend>Appointment Details</legend>

            <div class="mb-3">
                <label class="form-label" for="doctor">Preferred Doctor</label>
                <InputSelect id="doctor" class="form-select" @bind-Value="Model.Doctor"
                             @bind-Value:after="OnDoctorOrDateChanged">
                    <option value="">-- Select --</option>
                    @foreach (var doc in doctors)
                    {
                        <option value="@doc">@doc</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model.Doctor" />
                @if (serverErrors.ContainsKey(nameof(Model.Doctor)))
                {
                    <div class="validation-message">@serverErrors[nameof(Model.Doctor)]</div>
                }
            </div>

            <div class="mb-3">
                <label class="form-label" for="appointmentDate">Date</label>
                <InputDate id="appointmentDate" class="form-control" @bind-Value="Model.AppointmentDate"
                           @bind-Value:after="OnDoctorOrDateChanged" />
                <ValidationMessage For="() => Model.AppointmentDate" />
            </div>

            <div class="mb-3">
                <label class="form-label" for="timeSlot">Time Slot</label>
                <InputSelect id="timeSlot" class="form-select" @bind-Value="Model.TimeSlot">
                    <option value="">-- Select --</option>
                    @foreach (var slot in availableSlots)
                    {
                        <option value="@slot">@slot</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model.TimeSlot" />
                @if (serverErrors.ContainsKey(nameof(Model.TimeSlot)))
                {
                    <div class="validation-message">@serverErrors[nameof(Model.TimeSlot)]</div>
                }
            </div>

            <div class="mb-3">
                <label class="form-label" for="reason">Reason for Visit</label>
                <InputTextArea id="reason" class="form-control" @bind-Value="Model.ReasonForVisit" rows="3" />
                <ValidationMessage For="() => Model.ReasonForVisit" />
            </div>

            <div class="d-flex gap-2">
                <button type="button" class="btn btn-secondary" @onclick="BackToStep1">Back</button>
                <button type="button" class="btn btn-info" @onclick="CheckAvailability" disabled="@isChecking">
                    @(isChecking ? "Checking..." : "Check Availability")
                </button>
                <button type="submit" class="btn btn-success" disabled="@(!availabilityConfirmed)">
                    Book Appointment
                </button>
            </div>
        </fieldset>
    }
</EditForm>

@if (bookingConfirmed)
{
    <div class="alert alert-success mt-4">
        Appointment booked successfully for <strong>@Model.PatientName</strong>
        with <strong>@Model.Doctor</strong> on
        <strong>@Model.AppointmentDate?.ToString("d")</strong> at
        <strong>@Model.TimeSlot</strong>.
    </div>
}

@code {
    private BookAppointmentModel Model { get; set; } = new();
    private bool showStep2;
    private bool isChecking;
    private bool availabilityConfirmed;
    private bool bookingConfirmed;
    private List<string> doctors = new();
    private List<string> availableSlots = new();
    private Dictionary<string, string> serverErrors = new();
    private ValidationMessageStore? messageStore;
    private EditContext? editContext;

    protected override void OnInitialized()
    {
        editContext = new EditContext(Model);
        editContext.OnFieldChanged += (_, __) =>
        {
            // Clear server errors when user edits a field
            availabilityConfirmed = false;
            serverErrors.Clear();
            messageStore?.Clear();
        };
    }

    private async Task ProceedToStep2()
    {
        editContext = new EditContext(Model);
        messageStore = new ValidationMessageStore(editContext);

        // Validate only step-1 fields
        var isValid = true;
        if (string.IsNullOrWhiteSpace(Model.PatientName))
        {
            messageStore.Add(() => Model.PatientName, "Patient Name is required.");
            isValid = false;
        }
        if (string.IsNullOrWhiteSpace(Model.Email))
        {
            messageStore.Add(() => Model.Email, "Email is required.");
            isValid = false;
        }
        else if (!System.Text.RegularExpressions.Regex.IsMatch(
            Model.Email, @"^[^@\s]+@[^@\s]+\.[^@\s]+$"))
        {
            messageStore.Add(() => Model.Email, "Enter a valid email address.");
            isValid = false;
        }
        if (string.IsNullOrWhiteSpace(Model.Phone))
        {
            messageStore.Add(() => Model.Phone, "Phone is required.");
            isValid = false;
        }
        if (string.IsNullOrWhiteSpace(Model.InsuranceProvider))
        {
            messageStore.Add(() => Model.InsuranceProvider, "Insurance Provider is required.");
            isValid = false;
        }

        editContext.NotifyValidationStateChanged();

        if (!isValid) return;

        doctors = await AppointmentService.GetDoctorsAsync();
        showStep2 = true;
    }

    private void BackToStep1()
    {
        showStep2 = false;
        availabilityConfirmed = false;
        serverErrors.Clear();
    }

    private async Task OnDoctorOrDateChanged()
    {
        availableSlots.Clear();
        Model.TimeSlot = string.Empty;
        availabilityConfirmed = false;
        serverErrors.Clear();

        if (!string.IsNullOrEmpty(Model.Doctor) && Model.AppointmentDate.HasValue)
        {
            availableSlots = await AppointmentService.GetAvailableTimeSlotsAsync(
                Model.Doctor, DateOnly.FromDateTime(Model.AppointmentDate.Value));
        }
    }

    private async Task CheckAvailability()
    {
        serverErrors.Clear();
        messageStore?.Clear();
        editContext?.NotifyValidationStateChanged();
        availabilityConfirmed = false;

        // Validate step-2 fields locally first
        messageStore = new ValidationMessageStore(editContext!);
        var isValid = true;

        if (string.IsNullOrWhiteSpace(Model.Doctor))
        {
            messageStore.Add(() => Model.Doctor, "Preferred Doctor is required.");
            isValid = false;
        }
        if (!Model.AppointmentDate.HasValue)
        {
            messageStore.Add(() => Model.AppointmentDate, "Date is required.");
            isValid = false;
        }
        else if (Model.AppointmentDate.Value.Date <= DateTime.Today)
        {
            messageStore.Add(() => Model.AppointmentDate, "Date must be in the future.");
            isValid = false;
        }
        if (string.IsNullOrWhiteSpace(Model.TimeSlot))
        {
            messageStore.Add(() => Model.TimeSlot, "Time Slot is required.");
            isValid = false;
        }
        if (string.IsNullOrWhiteSpace(Model.ReasonForVisit))
        {
            messageStore.Add(() => Model.ReasonForVisit, "Reason for Visit is required.");
            isValid = false;
        }
        else if (Model.ReasonForVisit.Length > 500)
        {
            messageStore.Add(() => Model.ReasonForVisit, "Reason for Visit cannot exceed 500 characters.");
            isValid = false;
        }

        editContext!.NotifyValidationStateChanged();
        if (!isValid) return;

        // Server-side validation
        isChecking = true;
        try
        {
            var errors = await AppointmentService.ValidatePatientAsync(
                Model.Email, Model.InsuranceProvider, Model.Doctor, Model.TimeSlot);

            if (errors.Count > 0)
            {
                serverErrors = errors;
            }
            else
            {
                availabilityConfirmed = true;
            }
        }
        finally
        {
            isChecking = false;
        }
    }

    private void HandleSubmit()
    {
        if (!availabilityConfirmed) return;
        bookingConfirmed = true;
    }
}

